const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let sign = 1;
        if (buffer[offset] === 45) { // '-'
            sign = -1;
            offset++;
        }
        let res = 0;
        while (offset < buffer.length && buffer[offset] >= 48 && buffer[offset] <= 57) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res * sign;
    }

    const N = readInt();
    if (N === null) return;
    if (N <= 1) {
        console.log(0);
        return;
    }

    const X = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        X[i] = readInt();
    }

    const U = new Int32Array(N);
    const V = new Int32Array(N);

    let minU = Infinity, maxU = -Infinity;
    let minV = Infinity, maxV = -Infinity;

    for (let i = 0; i < N; i++) {
        const y = readInt();
        const x = X[i];
        const u = x + y;
        const v = x - y;
        U[i] = u;
        V[i] = v;
        if (u < minU) minU = u;
        if (u > maxU) maxU = u;
        if (v < minV) minV = v;
        if (v > maxV) maxV = v;
    }

    function check(D) {
        // Caso A:
        // Q1: u <= minU + D && v <= minV + D
        // Q2: u >= maxU - D && v >= maxV - D
        const limU1 = minU + D;
        const limV1 = minV + D;
        const limU2 = maxU - D;
        const limV2 = maxV - D;

        let okA = true;
        for (let i = 0; i < N; i++) {
            const u = U[i];
            const v = V[i];
            const inQ1 = (u <= limU1 && v <= limV1);
            const inQ2 = (u >= limU2 && v >= limV2);
            if (!inQ1 && !inQ2) {
                okA = false;
                break;
            }
        }
        if (okA) return true;

        // Caso B:
        // Q1: u <= minU + D && v >= maxV - D
        // Q2: u >= maxU - D && v <= minV + D
        let okB = true;
        for (let i = 0; i < N; i++) {
            const u = U[i];
            const v = V[i];
            const inQ1 = (u <= limU1 && v >= limV2);
            const inQ2 = (u >= limU2 && v <= limV1);
            if (!inQ1 && !inQ2) {
                okB = false;
                break;
            }
        }
        return okB;
    }

    let low = 0;
    let high = Math.max(maxU - minU, maxV - minV);
    let ans = high;

    while (low <= high) {
        const mid = (low + high) >> 1;
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    console.log(ans);
}

solve();
